create or replace TABLE SZD_PRODUCTION.CORE.T_FACT_DEPOSIT_CASH_DATA (
	RECEIPT_NR VARCHAR(16777216) NOT NULL COMMENT 'The unique identifier for a receipt generated by the cash',
	RECEIPT_DT DATE NOT NULL COMMENT 'The date of the generation of the receipt',
	RECEIPT_TM TIME(9) NOT NULL COMMENT 'The time of the generation of the receipt',
	STORE_NR VARCHAR(250) NOT NULL COMMENT 'The number by which the store is known to business. This number is unique for a given client_id, but not globally unique. (The same number can be in different clients).',
	DEPOSIT_RECEIPT_NR VARCHAR(16777216) NOT NULL COMMENT 'The deposit receipt number generated by the rvm.',
	COUNTRY_POL_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying a political country according to ISO 3166.',
	LOB_CD VARCHAR(50) NOT NULL COMMENT 'The code for the line of business within the Schwarz Group, i.e.Lidl or Kaufland lob=line os business',
	LOCAL_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the local currency according to ISO-4217.',
	DEPOSIT_OUTPAYMENT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The code for the way how the deposit amount can be paid back to the customer. (outpayment / donation / QR code / ...',
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a main store. It is identical to the key of the store that has first been assigned to this main store.',
	DEPOSIT_LOCAL_VAL NUMBER(38,5) NOT NULL COMMENT 'The deposit value in local currency from a deposit receipt',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	DEPOSIT_GLOBAL_VAL NUMBER(38,5) COMMENT 'The deposit value in global currency from a deposit receipt',
	GLOBAL_CURR_CD VARCHAR(3) COMMENT 'The global currency code-now it is set as EUR',
	constraint PK_T_FACT_DEPOSIT_CASH_DATA primary key (RECEIPT_NR, RECEIPT_DT, RECEIPT_TM, STORE_SID)
)COMMENT='Transactional facts capturing the daily cash outpayment data for deposit receipts'
;